window.CHAPTERS = [{"number": 1, "title": "Giới hạn, liên tục hàm nhiều biến số", "questions": [{"id": "2155", "text": "Giới hạn $\\lim \\limits_{(x,y)\\rightarrow (1;-1)} \\dfrac{x^2-y^2}{x+y}$ bằng\n<br/>\nThe limit $\\lim \\limits_{(x,y)\\rightarrow (1;-1)} \\dfrac{x^2-y^2}{x+y}$ is", "type": "single", "options": [{"id": "uuid1", "text": "$0.$"}, {"id": "uuid2", "text": "$1.$"}, {"id": "uuid3", "text": "$2.$"}, {"id": "uuid4", "text": "Không tồn tại.\n<br/>\nnon-existent."}], "answers": ["uuid3"]}, {"id": "342", "text": "Miền xác định của hàm số $z=\\sqrt{y}\\ln{(4-x^2-y^2)}$ là:", "type": "single", "options": [{"id": "uuid1", "text": "$x^2+y^2 < 4$ và $y\\ge0$"}, {"id": "uuid2", "text": "$x^2+y^2 > 4$"}, {"id": "uuid3", "text": "$x^2+y^2 \\leq 4$ và $y\\ge0$"}, {"id": "uuid4", "text": "$x^2+y^2 \\geq 4$ và $y\\ge0$"}], "answers": ["uuid1"]}, {"id": "2143", "text": "Miền xác định của hàm số $z=\\sqrt{y}\\ln{(4-x^2-y^2)}$ là\n<br/>\nThe domain of the function $z=\\sqrt{y}\\ln{(4-x^2-y^2)}$ is", "type": "single", "options": [{"id": "uuid1", "text": "$x^2+y^2 < 4$ và/and $y\\ge0$."}, {"id": "uuid2", "text": "$x^2+y^2 > 4$."}, {"id": "uuid3", "text": "$x^2+y^2 \\leq 4$ và/and  $y\\ge0$."}, {"id": "uuid4", "text": "$x^2+y^2 \\geq 4$ và/and  $y\\ge0$."}], "answers": ["uuid1"]}, {"id": "2138", "text": "Giới hạn $\\lim\\limits_{(x,y) \\rightarrow (3,1)} \\dfrac{x^2-9y^2}{x-3y}$ có giá trị là\n<br/>\nThe limit $\\lim\\limits_{(x,y) \\rightarrow (3,1)} \\dfrac{x^2-9y^2}{x-3y}$ is", "type": "single", "options": [{"id": "uuid1", "text": "$0$."}, {"id": "uuid2", "text": "$6$."}, {"id": "uuid3", "text": "$\\infty$."}, {"id": "uuid4", "text": "không tồn tại.\n<br/>\nnot existent."}], "answers": ["uuid2"]}, {"id": "2140", "text": "Giới hạn $\\lim\\limits_{(x,y) \\rightarrow (0,0)} \\dfrac{\\sin(xy)}{\\sqrt{x^2+y^2}}$ có giá trị là\n<br/>\nThe limit $\\lim\\limits_{(x,y) \\rightarrow (0,0)} \\dfrac{\\sin(xy)}{\\sqrt{x^2+y^2}}$ is", "type": "single", "options": [{"id": "uuid1", "text": "$0$."}, {"id": "uuid2", "text": "$1$."}, {"id": "uuid3", "text": "$\\infty$."}, {"id": "uuid4", "text": "Không tồn tại.\n<br/>\nnot existent."}], "answers": ["uuid1"]}, {"id": "2141", "text": "Chọn một phương án để hoàn thành định nghĩa sau: \"Hàm số $f(x,y)$ được gọi là liên tục trong miền xác định $D$ nếu hàm số đó ...\"\n<br/>\nChoose an option to complete the following definition: \"The function $f(x,y)$ is said to be continuous on the domain $D$ if the function is ...\"", "type": "single", "options": [{"id": "uuid1", "text": "liên tục tại một số điểm nào đó.\n<br/>\ncontinuous at some point."}, {"id": "uuid2", "text": "liên tục tại một số điểm thuộc $D$.\n<br/>\ncontinuous at some point in $D$."}, {"id": "uuid3", "text": "liên tục tại mọi điểm.\n<br/>\ncontinuous at every point."}, {"id": "uuid4", "text": "liên tục tại mọi điểm thuộc $D$.\n<br/>\ncontinuous at every point in $D$."}], "answers": ["uuid4"]}, {"id": "2152", "text": "Giới hạn của hàm số $ f(x, y) = \\dfrac{x^2y}{x^4 + y^2} $ khi $ (x, y) \\to (0; 0) $ là\n<br/>\nThe limit of the function $ f(x, y) = \\dfrac{x^2y}{x^4 + y^2} $ as $ (x, y) \\to (0; 0) $ is", "type": "single", "options": [{"id": "uuid1", "text": "0."}, {"id": "uuid2", "text": "1."}, {"id": "uuid3", "text": "không tồn tại.\n<br/>\nnon-existent."}, {"id": "uuid4", "text": "phụ thuộc vào $x$.\n<br/>\ndependent on $x$."}], "answers": ["uuid3"]}, {"id": "2153", "text": "Giới hạn $\\lim \\limits_{(x,y)\\rightarrow (0;0)} \\dfrac{x^2-3y^2}{x^2+3 y^2}$ bằng\n<br/>\nThe limit $\\lim \\limits_{(x,y)\\rightarrow (0;0)} \\dfrac{x^2-3y^2}{x^2+3 y^2}$ is", "type": "single", "options": [{"id": "uuid1", "text": "$0.$"}, {"id": "uuid2", "text": "$1.$"}, {"id": "uuid3", "text": "$-1.$"}, {"id": "uuid4", "text": "không tồn tại.\n<br/>\nnon-existent."}], "answers": ["uuid4"]}, {"id": "2149", "text": "Giới hạn của hàm số $ f(x, y) = \\dfrac{x^3 - y^3}{x^2 + y^2} $ khi $ (x, y) \\to (0; 0) $ theo phương của đường $ y = kx $ bằng\n<br/>\nThe limit of the function $f(x, y) = \\dfrac{x^3 - y^3}{x^2 + y^2}$ as $ (x, y) \\to (0; 0) $ along the line $ y = kx $ is", "type": "single", "options": [{"id": "uuid1", "text": "0."}, {"id": "uuid2", "text": "$k.$"}, {"id": "uuid3", "text": "$-k.$"}, {"id": "uuid4", "text": "một giá trị khác phụ thuộc vào $ k .$\n<br/>\nanother value depending on $k$."}], "answers": ["uuid1"]}, {"id": "2142", "text": "Các giá trị của $m$ để hàm số  $\\\\ \\quad f(x) = \\begin{cases}\n        \\dfrac{|x^2 y|^{m}}{x^4+y^2}, \\quad &(x,y) \\ne (0;0),\\\\\n        0, &(x,y) = (0;0)\n    \\end{cases} $ không liên tục tại điểm $(0;0)$ là\n<br/>\nThe values ​​of $m$ for the function $\\\\ \\quad f(x) = \\begin{cases}\n\\dfrac{|x^2 y|^{m}}{x^4+y^2}, \\quad &(x,y) \\ne (0;0),\\\\\n0, &(x,y) = (0;0)\n\\end{cases}$ to be discontinuous at the point $(0;0)$ are", "type": "single", "options": [{"id": "uuid1", "text": "$m > 1$."}, {"id": "uuid2", "text": "$m \\ne 0$."}, {"id": "uuid3", "text": "$m \\le 1$."}, {"id": "uuid4", "text": "$m \\ge 1$."}], "answers": ["uuid3"]}, {"id": "2151", "text": "Cho hàm số $ f(x, y) = e^{-(x^2 + y^2)} $. Những khẳng định nào sau đây là không đúng?\n<br/>\nGiven the function $ f(x, y) = e^{-(x^2 + y^2)} $. Which of the following statements are incorrect?", "type": "multi", "options": [{"id": "uuid1", "text": "Hàm số $ f(x, y)$ liên tục trên $\\mathbb{R}^2$.\n<br/>\nThe function $ f(x, y)$ is continuous on $\\mathbb{R}^2$."}, {"id": "uuid2", "text": "Hàm số $ f(x, y)$ không liên tục trên $\\mathbb{R}^2$.\n<br/>\nThe function $ f(x, y)$ is discontinuous on $\\mathbb{R}^2$."}, {"id": "uuid3", "text": "Hàm số $ f(x, y)$ chỉ liên tục tại gốc tọa độ.\n<br/>\nThe function $ f(x, y)$ is continuous only at the origin."}, {"id": "uuid4", "text": "Hàm số $ f(x, y)$ liên tục trên $\\mathbb{R}^2$ trừ một số điểm.\n<br/>\nThe function $ f(x, y)$ is continuous on $\\mathbb{R}^2$ except for some points."}], "answers": ["uuid2", "uuid3", "uuid4"]}, {"id": "2148", "text": "Giới hạn của hàm số $ f(x, y) = \\dfrac{x^2 - y^2}{x^2 + y^2} $ khi $ (x, y) \\to (0, 0) $ là\n<br/>\nThe limit of the function $ f(x, y) = \\dfrac{x^2 - y^2}{x^2 + y^2} $ as $ (x, y) \\to (0, 0) $ is", "type": "single", "options": [{"id": "uuid1", "text": "0."}, {"id": "uuid2", "text": "1."}, {"id": "uuid3", "text": "-1."}, {"id": "uuid4", "text": "không tồn tại.\n<br/>\nnon-existent."}], "answers": ["uuid4"]}, {"id": "2144", "text": "Giới hạn $\\lim\\limits_{(x,y) \\rightarrow (0,0)} \\dfrac{1-\\cos(x^2+y^2)}{(x^2+y^2)^2}$ có giá trị là\n<br/>\nThe limit $\\lim\\limits_{(x,y) \\rightarrow (0,0)} \\dfrac{1-\\cos(x^2+y^2)}{(x^2+y^2)^2}$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$\\infty$."}, {"id": "uuid2", "text": "$0$."}, {"id": "uuid3", "text": "$1/2$."}, {"id": "uuid4", "text": "$1$."}], "answers": ["uuid3"]}, {"id": "2146", "text": "Khẳng định nào sau đây về tính liên tục của hàm số \n$\\\\ f(x,y) = \\begin{cases}\n        \\dfrac{x^2-2y^2}{x^2+2y^2}, \\quad &(x,y) \\ne (0;0),\\\\\n        0, &(x,y) = (0;0)\n    \\end{cases} \\\\$\nlà đúng?\n<br/>\nWhich of the following statement about the continuity of the function\n$\\\\ f(x,y) = \\begin{cases}\n\\dfrac{x^2-2y^2}{x^2+2y^2}, \\quad &(x,y) \\ne (0;0),\\\\\n0, &(x,y) = (0;0)\n\\end{cases} \\\\$\nis true?", "type": "single", "options": [{"id": "uuid1", "text": "Hàm $f(x,y)$ liên tục tại mọi điểm $(x,y)$.\n<br/>\nThe function $f(x,y)$ is continuous at every point $(x,y)$."}, {"id": "uuid2", "text": "Hàm $f(x,y)$ liên tục tại mọi điểm $(x,y) \\ne (0,0)$.\n<br/>\nThe function $f(x,y)$ is continuous at every point $(x,y) \\ne (0,0)$."}, {"id": "uuid3", "text": "Hàm $f(x,y)$ không liên tục tại mọi điểm $(x,y)$.\n<br/>\nThe function $f(x,y)$ is discontinuous at every point $(x,y)$."}, {"id": "uuid4", "text": "Hàm $f(x,y)$ chỉ liên tục tại $(x,y) = (0,0)$.\n<br/>\nThe function $f(x,y)$ is only continuous at $(x,y) = (0,0)$."}], "answers": ["uuid2"]}, {"id": "2156", "text": "Giới hạn $\\lim \\limits_{(x,y)\\rightarrow (0;0)} \\dfrac{xy}{x^2+xy+y^2}$ bằng\n<br/>\nThe limit $\\lim \\limits_{(x,y)\\rightarrow (0;0)} \\dfrac{xy}{x^2+xy+y^2}$ is", "type": "single", "options": [{"id": "uuid1", "text": "$\\dfrac{1}{2}.$"}, {"id": "uuid2", "text": "$\\dfrac{1}{3}.$"}, {"id": "uuid3", "text": "$\\dfrac{1}{4}.$"}, {"id": "uuid4", "text": "không tồn tại.\n<br/>\nnon-existent."}], "answers": ["uuid4"]}, {"id": "2150", "text": "Giới hạn của hàm số $ f(x, y) = \\sqrt{x^2 + y^2} \\sin\\left(\\dfrac{1}{x^2 + y^2}\\right) $ khi $ (x, y) \\to (0; 0) $ là\n<br/>\nThe limit of the function $ f(x, y) = \\sqrt{x^2 + y^2} \\sin\\left(\\dfrac{1}{x^2 + y^2}\\right)$ as $ (x, y) \\to (0; 0) $ is", "type": "single", "options": [{"id": "uuid1", "text": "0."}, {"id": "uuid2", "text": "1."}, {"id": "uuid3", "text": "-1."}, {"id": "uuid4", "text": "không tồn tại.\n<br/>\nnon-existent."}], "answers": ["uuid1"]}, {"id": "2147", "text": "Hàm số $f(x,y) = \\begin{cases}\n        \\dfrac{\\cos{x}\\sin{y}}{2y}, \\quad & y \\ne 0,\\\\\n        2\\cos{x}, & y = 0\n    \\end{cases}$ liên tục trên miền nào sau đây?\n<br/>\nThe function $f(x,y) = \\begin{cases}\n\\dfrac{\\cos{x}\\sin{y}}{2y}, \\quad & y \\ne 0,\\\\\n2\\cos{x}, & y = 0\n\\end{cases}$ is continuous on the domain", "type": "single", "options": [{"id": "uuid1", "text": "$x^2+y^2 \\leq1$."}, {"id": "uuid2", "text": "$x-y \\geq 0$."}, {"id": "uuid3", "text": "$(x-2)^2+(y-3)^2 \\leq 1$."}, {"id": "uuid4", "text": "$(x-2)^2+(y-3)^2 \\leq 16$."}], "answers": ["uuid3"]}, {"id": "2145", "text": "Giới hạn $\\lim\\limits_{(x,y) \\rightarrow (0,0)} \\left(x \\sin{\\dfrac{1}{x}} + y \\sin{\\dfrac{1}{y}}\\right)$ có giá trị là\n<br/>\nThe limit $\\lim\\limits_{(x,y) \\rightarrow (0,0)} \\left(x \\sin{\\dfrac{1}{x}} + y \\sin{\\dfrac{1}{y}}\\right)$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$0$."}, {"id": "uuid2", "text": "$2$."}, {"id": "uuid3", "text": "$\\infty$."}, {"id": "uuid4", "text": "không tồn tại.\n<br/>\nnot existent."}], "answers": ["uuid1"]}, {"id": "2154", "text": "Giới hạn $\\lim \\limits_{(x,y)\\rightarrow (1;1)} (x+y) \\cos (x-y)$ bằng\n<br/>\nThe limit $\\lim \\limits_{(x,y)\\rightarrow (1;1)} (x+y) \\cos (x-y)$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$0.$"}, {"id": "uuid2", "text": "$1.$"}, {"id": "uuid3", "text": "$2.$"}, {"id": "uuid4", "text": "$3.$"}], "answers": ["uuid3"]}, {"id": "2139", "text": "Giới hạn $\\lim\\limits_{(x,y) \\rightarrow (0,0)} \\dfrac{x^3+2y^2+2}{3y^2}\\sin^2\\left(\\dfrac{y}{3}\\right)$ có giá trị là\n<br/>\nThe limit $\\lim\\limits_{(x,y) \\rightarrow (0,0)} \\dfrac{x^3+2y^2+2}{3y^2}\\sin^2\\left(\\dfrac{y}{3}\\right)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$2/9$."}, {"id": "uuid2", "text": "$0$."}, {"id": "uuid3", "text": "$2/27$."}, {"id": "uuid4", "text": "$1/3$."}], "answers": ["uuid3"]}, {"id": "2157", "text": "Giới hạn $\\lim \\limits_{(x,y)\\rightarrow (0;0)} (x^2+y^2)\\sin (\\dfrac{1}{x^2+y^2} )$ bằng\n<br/>\nThe limit $\\lim \\limits_{(x,y)\\rightarrow (0;0)} (x^2+y^2)\\sin (\\dfrac{1}{x^2+y^2} )$ is", "type": "single", "options": [{"id": "uuid1", "text": "$0.$"}, {"id": "uuid2", "text": "$1.$"}, {"id": "uuid3", "text": "$-1.$"}, {"id": "uuid4", "text": "không tồn tại.\n<br/>\nnon-existent."}], "answers": ["uuid1"]}]}, {"number": 2, "title": "Đạo hàm và vi phân hàm nhiều biến số", "questions": [{"id": "2211", "text": "Cho hàm số $f(x,y)=\\sqrt{x^2+y^2}.$ Đạo hàm riêng $f^{\\prime \\prime}_{xx}$ bằng\n<br/>\nGiven the function $f(x,y)=\\sqrt{x^2+y^2}.$ The partial derivative $f^{\\prime \\prime}_{xx}$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$\\dfrac{y}{(x^2+y^2)^{\\frac{1}{2}}}$"}, {"id": "uuid2", "text": "$\\dfrac{xy}{(x^2+y^2)^{\\frac{1}{2}}}$"}, {"id": "uuid3", "text": "$\\dfrac{x^2}{(x^2+y^2)^{\\frac{3}{2}}}$"}, {"id": "uuid4", "text": "$\\dfrac{y^2}{(x^2+y^2)^{\\frac{3}{2}}}$"}], "answers": ["uuid4"]}, {"id": "2212", "text": "Cho hàm số $z=ue^v,$ trong đó $u=u(x , y),v=v( x, y).$ Đạo hàm riêng $z^{\\prime}_x$ được tính theo công thức nào dưới đây?\n<br/>\nGiven the function $z=ue^v,$ where $u=u(x , y),v=v( x, y).$ The partial derivative $z^{\\prime}_x$ is calculated by", "type": "single", "options": [{"id": "uuid1", "text": "$z^{\\prime}_x=e^vu^{\\prime}_x+ue^vv^{\\prime}_x$."}, {"id": "uuid2", "text": "$z^{\\prime}_x=e^vv^{\\prime}_x+ue^vu^{\\prime}_x$."}, {"id": "uuid3", "text": "$z^{\\prime}_x=v^{\\prime}_x+e^vu^{\\prime}_x$."}, {"id": "uuid4", "text": "$z^{\\prime}_x=u^{\\prime}_x+e^vv^{\\prime}_x$."}], "answers": ["uuid1"]}, {"id": "2217", "text": "Đạo hàm riêng cấp hai $f''_{xy}(0;0)$ của hàm số $f(x,y)=e^{x+3y}$ là\n<br/>\nThe second partial derivative $f''_{xy}(0;0)$ of the function $f(x,y)=e^{x+3y}$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$0$."}, {"id": "uuid2", "text": "$4$."}, {"id": "uuid3", "text": "$1$."}, {"id": "uuid4", "text": "$3$."}, {"id": "uuid5", "text": "$2$."}], "answers": ["uuid4"]}, {"id": "2215", "text": "Cho hàm số $f(x, y) = e^{\\sin x} + x^5y + \\ln(1 + y^2).$ Đạo hàm riêng  $f^{\\prime \\prime}_{yx}$ bằng\n<br/>\nGiven the function $f(x, y) = e^{\\sin x} + x^5y + \\ln(1 + y^2).$ The partial derivative $f^{\\prime \\prime}_{yx}$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$\\dfrac{2y}{1+y^2}$."}, {"id": "uuid2", "text": "$20x^3y$."}, {"id": "uuid3", "text": "$5x^4$."}, {"id": "uuid4", "text": "$e^{\\sin x}\\cos x$."}], "answers": ["uuid3"]}, {"id": "2224", "text": "Cho hàm ẩn $z=z(x,y)$ xác định bởi phương trình $x^2+y^2+z^2=6$ trong lân cận của điểm $(1;1;2)$. Khi đó, $\\dfrac{\\partial z}{\\partial x} $ là\n<br/>\nLet the implicit function $z=z(x,y)$ be determined by the equation $x^2+y^2+z^2=6$ in a neighborhood of the point $(1;1;2)$. Then, $\\dfrac{\\partial }{\\partial x} $ is", "type": "single", "options": [{"id": "uuid1", "text": "$-\\dfrac{z}{x}$."}, {"id": "uuid2", "text": "$\\dfrac{z}{x}$."}, {"id": "uuid3", "text": "$-\\dfrac{x}{z}$."}, {"id": "uuid4", "text": "$\\dfrac{x}{z}$."}], "answers": ["uuid3"]}, {"id": "2222", "text": "Đạo hàm riêng cấp hai $\\dfrac{\\partial^2f(x,y)}{\\partial x\\partial y}$ của hàm số $f(x,y)=\\ln (x+y^2)$ là\n<br/>\nThe second partial derivative $\\dfrac{\\partial^2f(x,y)}{\\partial x\\partial y}$ of the function $f(x,y)=\\ln (x+y^2)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$\\dfrac{1}{(x+y^2)^2}$."}, {"id": "uuid2", "text": "$\\dfrac{-1}{(x+y^2)^2}$."}, {"id": "uuid3", "text": "$\\dfrac{-2y}{(x+y^2)^2}$."}, {"id": "uuid4", "text": "$\\dfrac{2y}{(x+y^2)^2}$."}], "answers": ["uuid3"]}, {"id": "2223", "text": "Cho hàm số $f(x,y)=x^4+y^4$ và kí hiệu toán tử Laplace $\\Delta f(x,y)=\\dfrac{\\partial^2 f(x,y)}{\\partial x^2}+\\dfrac{\\partial^2 f(x,y)}{\\partial y^2}$. Khi đó, giá trị của $\\Delta f(1;2)$ bằng\n<br/>\nGiven the function $f(x,y)=x^4+y^4$, and denote by $\\Delta f(x,y)=\\dfrac{\\partial^2 f(x,y)}{\\partial x^2}+\\dfrac{\\partial^2 f(x,y)}{\\partial y^2}$ the Laplace operator. Then, the value $\\Delta f(1;2)$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$60$."}, {"id": "uuid2", "text": "$8$."}, {"id": "uuid3", "text": "$12$."}, {"id": "uuid4", "text": "$30$."}], "answers": ["uuid1"]}, {"id": "2208", "text": "Cho hàm số $f(x,y)=(x^3+y^4)^5$. Giá trị của $ f^{\\prime \\prime}_{xy}-f^{\\prime \\prime}_{yx}$ tại điểm $(1;2)$ bằng\n<br/>\nGiven the function $f(x,y)=(x^3+y^4)^5$. The value of $ f^{\\prime \\prime}_{xy}-f^{\\prime \\prime}_{yx}$ at the point $(1;2)$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "0."}, {"id": "uuid2", "text": "2."}, {"id": "uuid3", "text": "-2."}, {"id": "uuid4", "text": "4."}], "answers": ["uuid1"]}, {"id": "2209", "text": "Cho hàm số $f(x,y)=\\sin(2x+y)$. Đạo hàm riêng $f^{\\prime \\prime}_{xy}(\\pi;\\frac{\\pi}{2})$ bằng\n<br/>\nGiven the function $f(x,y)=\\sin(2x+y)$. The partial derivative $f^{\\prime \\prime}_{xy}(\\pi;\\frac{\\pi}{2})$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$-2$."}, {"id": "uuid2", "text": "$2$."}, {"id": "uuid3", "text": "$\\sqrt{2}$."}, {"id": "uuid4", "text": "$-\\sqrt{2}$."}], "answers": ["uuid1"]}, {"id": "2206", "text": "Hàm số hai biến số $z=z(x,y)$ có thể có bao nhiêu các đạo hàm riêng cấp ba?\n<br/>\nHow many third-order partial derivatives can a function $z=z(x,y)$ of two variables have?", "type": "single", "options": [{"id": "uuid1", "text": "2."}, {"id": "uuid2", "text": "4."}, {"id": "uuid3", "text": "6."}, {"id": "uuid4", "text": "8."}], "answers": ["uuid4"]}, {"id": "2219", "text": "Những khẳng định nào sau đây là đúng?\n<br/>\nWhich of the following statements are true?", "type": "multi", "options": [{"id": "uuid1", "text": "Nếu hàm số $f(x, y)$ khả vi tại điểm $M_0(x_0, y_0)$ thì hàm số $f(x, y)$ liên tục tại $M_0$.\n<br/>\nIf a function $f(x, y)$ is differentiable at the point $M_0(x_0, y_0)$, then it is continuous at $M_0$."}, {"id": "uuid2", "text": "Nếu hàm số $f(x, y)$ khả vi tại điểm $M_0(x_0, y_0)$ thì hàm số $f(x, y)$ có các đạo hàm riêng tại $M_0$.\n<br/>\nIf a function $f(x, y)$ is differentiable at the point $M_0(x_0, y_0)$, then it has partial derivatives at $M_0$."}, {"id": "uuid3", "text": "Nếu hàm số $f(x, y)$ có các đạo hàm riêng tại điểm $M_0(x_0, y_0)$ thì hàm số $f(x, y)$ liên tục tại $M_0$.\n<br/>\nIf a function $f(x, y)$ has partial derivatives at the point $M_0(x_0, y_0)$, then it is continuous at $M_0$."}, {"id": "uuid4", "text": "Nếu hàm số $f(x, y)$ có các đạo hàm riêng tại điểm $M_0(x_0, y_0)$ thì hàm số $f(x, y)$ khả vi tại $M_0$.\n<br/>\nIf a function $f(x, y)$ has partial derivatives at the point $M_0(x_0, y_0)$, then it is differentiable at $M_0$."}], "answers": ["uuid1", "uuid2"]}, {"id": "2214", "text": "Cho hàm ẩn $z=z(x,y)$ xác định bởi phương trình $e^z=x+y+z.$ Đạo hàm riêng $z^{\\prime}_x$ bằng\n<br/>\nLet $z=z(x,y)$ be an implicit function defined by the equation $e^z=x+y+z.$ The partial derivative $z^{\\prime}_x$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$\\dfrac{1}{x+y+z}$"}, {"id": "uuid2", "text": "$\\dfrac{1}{x+y+z-1}$"}, {"id": "uuid3", "text": "$\\dfrac{1}{x+y+z+1}$"}, {"id": "uuid4", "text": "$\\dfrac{1}{x+y}$"}], "answers": ["uuid2"]}, {"id": "2221", "text": "Cho hàm số $f(x,y)=\\sqrt{x^2+y^2}$. Khi đó, giá trị của đạo hàm riêng $\\dfrac{\\partial f}{\\partial y}(3;4)$ bằng\n<br/>\nGiven the function $f(x,y)=\\sqrt{x^2+y^2}$. The value of the partial derivative $\\dfrac{\\partial f}{\\partial y}(3;4)$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$\\dfrac{3}{5}$."}, {"id": "uuid2", "text": "$\\dfrac{4}{5}$."}, {"id": "uuid3", "text": "$-\\dfrac{4}{5}$."}, {"id": "uuid4", "text": "$-\\dfrac{3}{5}$."}], "answers": ["uuid2"]}, {"id": "2213", "text": "Cho hàm số $z=x+\\sin(\\frac{y}{x}),$ trong đó $y=x^2.$ Khi đó $\\dfrac{dz}{dx}$ bằng\n<br/>\nGiven the function $z=x+\\sin(\\frac{y}{x}),$ where $y=x^2.$ Then $\\dfrac{dz}{dx}$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$1+\\sin x$."}, {"id": "uuid2", "text": "$1-\\sin x$."}, {"id": "uuid3", "text": "$1+\\cos x$."}, {"id": "uuid4", "text": "$1-\\cos x$."}], "answers": ["uuid3"]}, {"id": "2220", "text": "Cho hàm số $f(x,y)=x^2+y^2$. Khi đó, vi phân toàn phần của hàm số $f(x,y)$ tại $(1;2)$ là\n<br/>\nGiven the function $f(x,y)=x^2+y^2$. The total differential of the function $f(x,y)$ at $(1;2)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$df(1;2)=2dx+4dy$."}, {"id": "uuid2", "text": "$df(1;2)=2dx-4dy$."}, {"id": "uuid3", "text": "$df(1;2)=2dx+2dy$."}, {"id": "uuid4", "text": "$df(1;2)=4dx+4dy$."}], "answers": ["uuid1"]}, {"id": "2210", "text": "Cho hàm số $f(x,y)=e^{2x+y^2}.$ Giá trị của đạo hàm riêng $f^{\\prime \\prime}_{xx}(0;0)$ bằng\n<br/>\nGiven the function $f(x,y)=e^{2x+y^2}.$ The partial derivative $f^{\\prime \\prime}_{xx}(0;0)$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$2$."}, {"id": "uuid2", "text": "$4$."}, {"id": "uuid3", "text": "$2e$."}, {"id": "uuid4", "text": "$4e$."}], "answers": ["uuid2"]}, {"id": "2218", "text": "Cho hàm số $f(x, y)=\\sin(x+y)$ với $x=2t$, $y=t^3$. Khi đó đạo hàm $\\dfrac{df}{dt}|_{t=0}$ bằng\n<br/>\nGiven the function $f(x, y)=\\sin(x+y)$, where $x=2t$, $y=t^3$. Then, the derivative $\\dfrac{df}{dt}|_{t=0}$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$0$."}, {"id": "uuid2", "text": "$4$."}, {"id": "uuid3", "text": "$1$."}, {"id": "uuid4", "text": "$3$."}, {"id": "uuid5", "text": "$2$."}], "answers": ["uuid5"]}, {"id": "2216", "text": "Vi phân toàn phần $df(1; 1)$ của hàm số $f(x,y)=\\ln(2x-y)$ là\n<br/>\nThe total differential $df(1; 1)$ of the function $f(x,y)=\\ln(2x-y)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$dx+dy$."}, {"id": "uuid2", "text": "$2dx-dy$."}, {"id": "uuid3", "text": "$2dx+dy$."}, {"id": "uuid4", "text": "$dx-2dy$."}, {"id": "uuid5", "text": "$dx+2dy$."}], "answers": ["uuid2"]}, {"id": "2205", "text": "Vi phân cấp hai $d^2f(1; 0)$ của hàm số $f(x,y)=x^2+xy-2y^2$ là\n<br/>\nThe second-order total differential $d^2f(1; 0)$ of the function $f(x,y)=x^2+xy-2y^2$ is", "type": "single", "options": [{"id": "uuid1", "text": "$dx^2+2dxdy-4dy^2$."}, {"id": "uuid2", "text": "$2dx^2+2dxdy+4dy^2$."}, {"id": "uuid3", "text": "$dx^2+dxdy-2dy^2$."}, {"id": "uuid4", "text": "$dx^2+2dxdy-2dy^2$"}, {"id": "uuid5", "text": "$2dx^2+2dxdy-4dy^2$."}], "answers": ["uuid5"]}, {"id": "2204", "text": "Cho hàm số $f(x, y,z) = x^2 + xyz + z$. Đạo hàm riêng $f'_x(1,1,1)$ bằng\n<br/>\nGiven the function $f(x, y,z) = x^2 + xyz + z$. The partial derivative $f'_x(1,1,1)$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$0$."}, {"id": "uuid2", "text": "$1$."}, {"id": "uuid3", "text": "$3$."}, {"id": "uuid4", "text": "$-1$."}], "answers": ["uuid3"]}]}, {"number": 3, "title": "Cực trị của hàm số nhiều biến số", "questions": [{"id": "2230", "text": "Kết luận về cực trị của hàm số $z=x^3+3xy-9x-y+y^2+4$ là\n<br/>\nThe conclusion about the local extreme values of the function $z=x^3+3xy-9x-y+y^2+4$ is", "type": "multi", "options": [{"id": "uuid1", "text": "Hàm số không đạt cực trị tại $(-1, 2)$.\n<br/>\nThe function does not attain a local extreme value at $(-1, 2)$."}, {"id": "uuid2", "text": "$z_{ \\rm CT}=z(-1, 2)=8$."}, {"id": "uuid3", "text": "Hàm số không đạt cực trị tại $(\\frac{5}{2}, -\\frac{13}{4})$.\n<br/>\nThe function does not attain a local extreme value at $(\\frac{5}{2}, -\\frac{13}{4})$."}, {"id": "uuid4", "text": "Hàm số đạt cực tiểu tại $(\\frac{5}{2}, -\\frac{13}{4})$.\n<br/>\nThe function attains a local minimum at $(\\frac{5}{2}, -\\frac{13}{4})$."}], "answers": ["uuid1", "uuid4"]}, {"id": "2237", "text": "Cho hàm $z=f(x,y)$ có các đạo hàm cấp riêng đến cấp hai liên tục trong một lân cận nào đó của điểm $M_0$ và $f'_x(M_0)= f'_y(M_0)=0$. Khi đó, nếu $(f''_{xy}(M_0))^2 - f''_{xx}(M_0) f''_{yy}(M_0) < 0$ và $f''_{xx}(M_0) > 0$ thì\n<br/>\nLet $z=f(x,y)$ have continuous partial derivatives up to the second order in a neighborhood of the point $M_0$ and $f'_x(M_0)= f'_y(M_0)=0.$ If $(f''_{xy}(M_0))^2 - f''_{xx}(M_0) f''_{yy}(M_0) < 0$ and $f''_{xx}(M_0) > 0$, then", "type": "single", "options": [{"id": "uuid1", "text": "hàm $f(x,y)$ đạt cực đại tại $M_0$.\n<br/>\nthe function $f(x,y)$ attains a local maximum at $M_0$."}, {"id": "uuid2", "text": "hàm $f(x,y)$ đạt cực tiểu tại $M_0$.\n<br/>\nthe function $f(x,y)$ attains a local minimum at $M_0$."}, {"id": "uuid3", "text": "hàm $f(x,y)$  không đạt cực trị tại $M_0$.\n<br/>\nthe function $f(x,y)$ does not attain a local extremum at $M_0$."}, {"id": "uuid4", "text": "hàm $f(x,y)$ không đạt cực tiểu tại $M_0$.\n<br/>\nthe function $f(x,y)$ does not attain a local minimum at $M_0$."}], "answers": ["uuid2"]}, {"id": "2231", "text": "Cực trị của hàm số $z=2x^2+y^2+2$ với điều kiện $x^2+y^2=1$ là\n<br/>\nThe local extreme values of the function $z=2x^2+y^2+2$ under the constraint $x^2+y^2=1$ are", "type": "multi", "options": [{"id": "uuid1", "text": "$z_{\\rm CĐ}=z(\\pm 1, 0)=4$."}, {"id": "uuid2", "text": "$z_{\\rm CT}=z(\\pm\\frac{1}{2}, \\pm\\frac{\\sqrt{3}}{2})=\\frac{13}{4}$."}, {"id": "uuid3", "text": "$z_{\\rm CĐ}=z(\\pm\\frac{\\sqrt{3}}{2}, \\pm\\frac{1}{2})=\\frac{15}{4}$."}, {"id": "uuid4", "text": "$z_{\\rm CT}=z(0, \\pm 1)=3$."}], "answers": ["uuid1", "uuid4"]}, {"id": "2245", "text": "Giá trị cực đại của hàm số $f(x,y)=xy$ với điều kiện $x+2y=1$ là\n<br/>\nThe maximum value of the function $f(x,y)=xy$ under the constraint $x+2y=1$ is", "type": "single", "options": [{"id": "uuid1", "text": "$\\dfrac{1}{8}$."}, {"id": "uuid2", "text": "$\\dfrac{1}{4}$."}, {"id": "uuid3", "text": "$\\dfrac{1}{2}$."}, {"id": "uuid4", "text": "$\\dfrac{1}{16}$."}], "answers": ["uuid1"]}, {"id": "2234", "text": "Cực trị của hàm số $z=x^2+y^2$ với điều kiện $3x-y=2$ là\n<br/>\nThe extreme value of the function $z=x^2+y^2$ under the constraint $3x-y=2$ is", "type": "single", "options": [{"id": "uuid1", "text": "$z_{{\\rm CT}}=z(\\frac{3}{5}; -\\frac{1}{5})=\\frac{2}{5}$."}, {"id": "uuid2", "text": "Hàm số không có cực trị.\n<br/>\nThe function does not have any extreme values."}, {"id": "uuid3", "text": "$z_{{\\rm CT}}=z(1; 1)=2$."}, {"id": "uuid4", "text": "$z_{{\\rm CĐ}}=z(1; 1)=2$."}], "answers": ["uuid1"]}, {"id": "2239", "text": "Hàm số $z = x^2 + \\dfrac{2}{x} + y + \\dfrac{9}{y}$ có mấy điểm tới hạn?\n<br/>\nHow many critical points does the function $z = x^2 + \\dfrac{2}{x} + y + \\dfrac{9}{y}$ have?", "type": "single", "options": [{"id": "uuid1", "text": "$0$."}, {"id": "uuid2", "text": "$1$."}, {"id": "uuid3", "text": "$2$."}, {"id": "uuid4", "text": "$3$."}], "answers": ["uuid3"]}, {"id": "2242", "text": "Cho hàm số $f(x,y)$ và giả sử $f'_x(x_0,y_0)$ và $f'_y(x_0,y_0)$ tồn tại. Khi đó điều kiện $f'_x(x_0,y_0)=f'_y(x_0,y_0)=0$ là điều kiện gì để hàm số đạt cực trị tại $(x_0,y_0)$?\n<br/>\nGiven a function $f(x,y)$ that $f'_x(x_0,y_0)$ and $f'_y(x_0,y_0)$ exist. What kind of conditions for $f(x,y)$ to attain a local extremum at $(x_0,y_0)$ is the condition $f'_x(x_0,y_0)=f'_y(x_0,y_0)=0$?", "type": "single", "options": [{"id": "uuid1", "text": "Điều kiện cần.\n<br/>\nA necessary condition."}, {"id": "uuid2", "text": "Điều kiện đủ.\n<br/>\nA sufficient condition."}, {"id": "uuid3", "text": "Điều kiện cần và đủ.\n<br/>\nA necessary and sufficient condition."}, {"id": "uuid4", "text": "Điều kiện không bắt buộc.\n<br/>\nAn optional condition."}], "answers": ["uuid1"]}, {"id": "2246", "text": "Cho $A\\subset\\mathbb{R}^2$ là tập đóng và bị chặn. Hàm số $f:A\\rightarrow\\mathbb{R}$ liên tục sẽ\n<br/>\nLet $A\\subset\\mathbb{R}^2$ be a closed and bounded set. A continuous function $f:A\\rightarrow\\mathbb{R}$", "type": "single", "options": [{"id": "uuid1", "text": "đạt giá trị lớn nhất và nhỏ nhất trên $A$.\n<br/>\nattains its absolute maximum and minimum values ​​on $A$."}, {"id": "uuid2", "text": "không đạt giá trị lớn nhất và nhỏ nhất trên $A$.\n<br/>\ndoes not attain its absolute maximum and minimum values ​​on $A$."}, {"id": "uuid3", "text": "đạt giá trị lớn nhất và không đạt giá trị nhỏ nhất trên $A$.\n<br/>\nattains its absolute maximum value but does not attain its absolute minimum value on $A$."}, {"id": "uuid4", "text": "đạt giá trị nhỏ nhất và không đạt giá trị lớn nhất trên $A$.\n<br/>\nattains its absolute minimum value but does not attain its absolute maximum value on $A$."}], "answers": ["uuid1"]}, {"id": "2232", "text": "Các điểm tới hạn của hàm số $z=x^4+y^4-2x^2+2y^2+6$ là\n<br/>\nThe critical points of the function $z=x^4+y^4-2x^2+2y^2+6$ are", "type": "single", "options": [{"id": "uuid1", "text": "$M_1(0; 0), M_2(2; 0), M_3(-2; 0)$."}, {"id": "uuid2", "text": "$M_1(0; 0), M_2(0; 1), M_3(0; -1)$."}, {"id": "uuid3", "text": "$M_1(0; 0), M_2(1; 0), M_3(-1; 0)$."}, {"id": "uuid4", "text": "$M_1(2; 0), M_2(0; 2)$."}], "answers": ["uuid3"]}, {"id": "1791", "text": "Điểm tới hạn của một hàm số nhiều biến là:", "type": "single", "options": [{"id": "uuid1", "text": "điểm cực trị của hàm số đó."}, {"id": "uuid2", "text": "điểm tại đó tất cả các đạo hàm riêng cấp một của hàm bằng 0."}, {"id": "uuid3", "text": "điểm tại đó tất cả các đạo hàm riêng cấp một của hàm khác 0."}, {"id": "uuid4", "text": "điểm tại đó tất cả các đạo hàm riêng cấp một của hàm bằng 0 hoặc có ít nhất một đạo hàm riêng không tồn tại."}], "answers": ["uuid4"]}, {"id": "2227", "text": "Điểm tới hạn của hàm số $z=2x^2+3y^2-e^{-(x^2+y^2)}$ là\n<br/>\nThe critical point of the function $z=2x^2+3y^2-e^{-(x^2+y^2)}$ is", "type": "single", "options": [{"id": "uuid1", "text": "$M(1;0)$."}, {"id": "uuid2", "text": "$M(0;1)$."}, {"id": "uuid3", "text": "$M(0;0)$."}, {"id": "uuid4", "text": "$M(1;1)$."}], "answers": ["uuid3"]}, {"id": "2243", "text": "Cho hàm số $f(x,y)$ có các đạo hàm riêng đến cấp hai liên tục trong lân cận của điểm dừng $(x_0,y_0)$. Khi đó nếu $f''_{xx}(x_0,y_0)f''_{yy}(x_0,y_0)<0$ thì $(x_0,y_0)$ là điểm gì trong các loại sau?\n<br/>\nLet the function $f(x,y)$ have continuous partial derivatives up to the second order in a neighborhood of the stationary point $(x_0,y_0)$. Which type of points is  $(x_0,y_0)$ if $f''_{xx}(x_0,y_0)f''_{yy}(x_0,y_0)<0$?", "type": "single", "options": [{"id": "uuid1", "text": "Không là cực trị.\n<br/>\nNot a local extreme point."}, {"id": "uuid2", "text": "Cực đại.\n<br/>\nA local maximum point."}, {"id": "uuid3", "text": "Cực tiểu.\n<br/>\nA local minimum point."}, {"id": "uuid4", "text": "Cực trị.\n<br/>\nA local extremum point."}], "answers": ["uuid1"]}, {"id": "2241", "text": "Cho hàm $z=f(x,y)$ xác định trong miền $D \\subset \\mathbb{R}^2$. Hàm $f(x,y)$ đạt cực tiểu tại $M_0(x_0,y_0) \\in D$ nếu với mọi điểm $M(x,y) \\in D$ khác $M_0$ và nằm trong lân cận nào đó của $M_0$, thì hiệu $f(M)-f(M_0)$\n<br/>\nGiven a function $z=f(x,y)$ defined on a domain $D \\subset \\mathbb{R}^2$. The function $f(x,y)$ attains a local minimum at $M_0(x_0,y_0) \\in D$ if for every point $M(x,y) \\in D$ other than $M_0$ and in some neighborhood of $M_0$, then the difference $f(M)-f(M_0)$", "type": "single", "options": [{"id": "uuid1", "text": "luôn dương.\n<br/>\nis always positive."}, {"id": "uuid2", "text": "luôn âm.\n<br/>\nis always negative."}, {"id": "uuid3", "text": "có dấu thay đổi.\n<br/>\nchanges the sign."}, {"id": "uuid4", "text": "luôn bằng 0.\n<br/>\nis always 0."}], "answers": ["uuid1"]}, {"id": "2228", "text": "Cực trị của hàm số $z=e^x(-x-2y-y^2)$ là\n<br/>\nThe local extreme value of the function $z=e^x(-x-2y-y^2)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$z_{{\\rm CT}}=z(0;1)=-1$."}, {"id": "uuid2", "text": "$z_{{\\rm CĐ}}=z(0;-1)=1$."}, {"id": "uuid3", "text": "$z_{{\\rm CĐ}}=z(0;0)=2$."}, {"id": "uuid4", "text": "$z_{{\\rm CT}}=z(0;0)=2$."}], "answers": ["uuid2"]}, {"id": "2229", "text": "Cực trị của hàm số $z=-x\\ln x-y\\ln y$ với điều kiện $x+y=1 \\ (x,y>0)$ là\n<br/>\nThe local extreme values of the function $z=-x\\ln x-y\\ln y$ subject to the constraint $x+y=1 \\ (x,y>0)$ are", "type": "single", "options": [{"id": "uuid1", "text": "$z_{{\\rm CĐ}}=z(\\frac{1}{2}, \\frac{1}{2})=\\ln 2$."}, {"id": "uuid2", "text": "Hàm số không có điểm cực trị.\n<br/>\nThe function does not have any extreme values."}, {"id": "uuid3", "text": "$z_{{\\rm CĐ}}=z(\\frac{1}{3}, \\frac{2}{3})=\\ln 3-\\frac{2}{3}\\ln 2$."}, {"id": "uuid4", "text": "$z_{{\\rm CT}}=z(\\frac{1}{3}, \\frac{2}{3})=\\ln 3-\\frac{2}{3}\\ln 2$."}], "answers": ["uuid1"]}, {"id": "2233", "text": "Theo phương pháp nhân tử Lagrange, điểm tới hạn của hàm số $z=x^2+2y^2+2$ với điều kiện $x^2+y^2=1$, $x, y \\ge 0$ có tọa độ là\n<br/>\nAccording to the Lagrange multiplier method, the critical point of the function $z=x^2+2y^2+2$ subject to the constraint $x^2+y^2=1$, $x, y \\ge 0$ are", "type": "single", "options": [{"id": "uuid1", "text": "$M(\\frac{\\sqrt{2}}{2};\\frac{\\sqrt{2}}{2})$."}, {"id": "uuid2", "text": "$M(\\frac{1}{2};\\frac{\\sqrt{3}}{2})$."}, {"id": "uuid3", "text": "$M(1;0), \\ N(0;1)$."}, {"id": "uuid4", "text": "$M(\\frac{1}{2};\\frac{\\sqrt{3}}{2}), N(\\frac{\\sqrt{3}}{2}; \\frac{1}{2})$."}], "answers": ["uuid3"]}, {"id": "2236", "text": "Kết luận về giá trị lớn nhất, bé nhất của hàm số $z=x^2+2y-xy$ trong miền tam giác $OAB$, với $O(0;0), \\ A(1; 0), \\ B(0; 1)$ là\n<br/>\nThe global maximum and minimum values ​​of the function $z=x^2+2y-xy$ in the triangular domain $OAB$, where $O(0;0), \\ A(1; 0), \\ B(0; 1)$, are", "type": "multi", "options": [{"id": "uuid1", "text": "$z_{\\rm max}=z(0;1)=2$."}, {"id": "uuid2", "text": "$z_{\\rm min}=z(1;-4)=-3$."}, {"id": "uuid3", "text": "$z_{\\rm max}=z(2;4)=4$."}, {"id": "uuid4", "text": "$z_{\\rm min}=z(0; 0)=0$."}], "answers": ["uuid1", "uuid4"]}, {"id": "2244", "text": "Hàm số $f(x,y)=x^3+(y-1)^2$ có bao nhiêu điểm cực trị?\n<br/>\nHow many extreme points does the function $f(x,y)=x^3+(y-1)^2$ have?", "type": "single", "options": [{"id": "uuid1", "text": "$0$."}, {"id": "uuid2", "text": "$1$."}, {"id": "uuid3", "text": "$2$."}, {"id": "uuid4", "text": "$3$."}], "answers": ["uuid1"]}, {"id": "2240", "text": "Hàm số $z =x^4 + y^4 - 2x^2 + 4xy -2y^2$ có bao nhiêu điểm tới hạn?\n<br/>\nHow many critical points does the function $z =x^4 + y^4 - 2x^2 + 4xy -2y^2$ have?", "type": "single", "options": [{"id": "uuid1", "text": "Một điểm tới hạn.\n<br/>\nOne critical point."}, {"id": "uuid2", "text": "Hai điểm tới hạn.\n<br/>\nTwo critical points."}, {"id": "uuid3", "text": "Ba điểm tới hạn.\n<br/>\nThree critical points."}, {"id": "uuid4", "text": "Bốn điểm tới hạn.\n<br/>\nFour critical points."}], "answers": ["uuid3"]}, {"id": "2235", "text": "Kết luận về cực trị của hàm số $z=x^4+y^4+2x^2-2y^2+2$ là\n<br/>\nThe conclusion about the extreme values of the function $z=x^4+y^4+2x^2-2y^2+2$ is that", "type": "multi", "options": [{"id": "uuid1", "text": "Hàm số không đạt cực trị tại $(0;0)$.\n<br/>\nThe function does not attain a local extremum at $(0;0)$."}, {"id": "uuid2", "text": "$z_{ \\rm CT}=z(1; 1)=4$."}, {"id": "uuid3", "text": "Hàm số không đạt cực trị tại $(0; 1)$.\n<br/>\nThe function does not attain a local extremum at $(0;1)$."}, {"id": "uuid4", "text": "$z_{\\rm CT}=z(0; \\pm 1)=1$."}], "answers": ["uuid1", "uuid4"]}]}, {"number": 4, "title": "Ứng dụng của phép tính vi phân trong hình học phẳng", "questions": [{"id": "2583", "text": "Cho đường cong $C$ có phương trình $f(x,y)=0$ và $M\\in C$ là điểm chính quy. Khi đó, tiếp tuyến tại $M$ và pháp tuyến tại $M$\n<br/><br/>\nGiven a curve $C$ with equation $f(x,y)=0$ and $M\\in C$ is a regular point. Then the tangent line at $M$ and the normal line at $M$", "type": "single", "options": [{"id": "uuid1", "text": "song song với nhau (are parallel to each other)."}, {"id": "uuid2", "text": "vuông góc với nhau (are perpendicular to each other)."}, {"id": "uuid3", "text": "tạo với nhau một góc $30^\\circ$ (make a $30$-degree angle)."}, {"id": "uuid4", "text": "tạo với nhau một góc $40^\\circ$ (make a $40$-degree angle)."}], "answers": ["uuid2"]}, {"id": "2584", "text": "Cho đường cong $C$ có phương trình $x^2+y^2-1=0$. Khi đó, phương trình tiếp tuyến của đường cong $C$ tại điểm $(1;0)$ là\n<br/><br/>\nLet $C$ be the curve given by $x^2+y^2-1=0$. The tangent line of $C$ at the point $(1,0)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$x=-1$."}, {"id": "uuid2", "text": "$x=1$."}, {"id": "uuid3", "text": "$y=0$."}, {"id": "uuid4", "text": "$y=1$."}], "answers": ["uuid2"]}, {"id": "2582", "text": "Cho đường cong $C$ có phương trình $f(x,y)=0$  và điểm chính quy $M(a,b)\\in C$. Véc tơ $\\overrightarrow{n}$ nào sau đây là  một vectơ pháp tuyến của $C$ tại điểm $M$?\n<br/><br/>\nLet $C$ be a curve defined by an equation $f(x,y)=0$, and let  $M(a,b)\\in C$ be a regular point. Which of the following vector $\\overrightarrow{n}$  is a normal vector of $C$ at the point $M$?", "type": "single", "options": [{"id": "uuid1", "text": "$\\overrightarrow{n}=((f_x'(a,b))^2+1,(f_y'(a,b))^2+1)$."}, {"id": "uuid2", "text": "$\\overrightarrow{n}=(f_x'(a,b)-1,f_y'(a,b)-1)$."}, {"id": "uuid3", "text": "$\\overrightarrow{n}=(f_x'(a,b),f_y'(a,b))$."}, {"id": "uuid4", "text": "$\\overrightarrow{n}=(f_x'(a,b)+1,f_y'(a,b)+1)$."}], "answers": ["uuid3"]}, {"id": "2672", "text": "Trong các điểm sau, những điểm nào là điểm nào điểm kỳ dị của đường cong $C$ được cho bởi phương trình $x^2(x-1)^2-y^2=0$?\n<br/><br/>\nWhich of the followings are singular points of the curve $C$ given by the equation $x^2(x-1)^2-y^2=0$?", "type": "multi", "options": [{"id": "uuid1", "text": "$(0;0)$."}, {"id": "uuid2", "text": "$(1;-1)$."}, {"id": "uuid3", "text": "$(-1;1)$."}, {"id": "uuid4", "text": "$(1;0)$."}], "answers": ["uuid1", "uuid4"]}, {"id": "2927", "text": "Cho đường cong $x^3 + y^3 = 9$. Tìm phương trình pháp tuyến của đường cong tại điểm $M(1;2)$.   <br/><br/> Given the curve $x^3 + y^3 = 9$, find an equation of the  normal line to the curve at the point $M(1, 2)$.", "type": "single", "options": [{"id": "uuid1", "text": "$x - 4y + 7 = 0$"}, {"id": "uuid2", "text": "$2x + y - 4 = 0$"}, {"id": "uuid3", "text": "$x + 2y - 5 = 0$"}, {"id": "uuid4", "text": "$4x - y - 2 = 0$"}], "answers": ["uuid4"]}, {"id": "2585", "text": "Cho đường cong $C$ có phương trình $x^2+y^2-4=0$. Khi đó, phương trình pháp tuyến của đường cong $C$ tại điểm $(2;0)$ là\n<br/><br/>\nLet $C$ be the curve given by $x^2+y^2-4=0$. Then the normal line of $C$ at the point $(2,0)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$x=-2$."}, {"id": "uuid2", "text": "$y=0$."}, {"id": "uuid3", "text": "$x=2$."}, {"id": "uuid4", "text": "$y=1$."}], "answers": ["uuid2"]}, {"id": "2929", "text": "Cho đường cong $ y = e^{1 - x^2} $. Tìm phương trình tiếp tuyến của đường cong tại điểm $ (1, 1) $. <br/><br/>Given the curve $ y = e^{1 - x^2} $, find an equation of the tangent line to the curve at the point $ (1, 1) $.", "type": "single", "options": [{"id": "uuid1", "text": "$ y = -2x + 3 $"}, {"id": "uuid2", "text": "$ y = 2x + 1 $"}, {"id": "uuid3", "text": "$ y = 1 $"}, {"id": "uuid4", "text": "$ y = -x + 3 $"}], "answers": ["uuid1"]}, {"id": "2934", "text": "Cho đường cong tham số:\n$\\begin{cases}\nx = t^3 - 3t, \\\\\ny = t^2 - 2t.\n\\end{cases}$\nTìm phương trình tiếp tuyến của đường cong tại điểm ứng với $t = 1$.  <br/><br/>\nGiven the parametric curve:\n$\n\\begin{cases}\nx = t^3 - 3t, \\\\\ny = t^2 - 2t,\n\\end{cases}\n$\nfind an equation of  the tangent line to the curve  at the point corresponding to $t = 1$.", "type": "single", "options": [{"id": "uuid1", "text": "$y = -x + 2$."}, {"id": "uuid2", "text": "$y = x - 2$."}, {"id": "uuid3", "text": "$y = 2x - 1$."}, {"id": "uuid4", "text": "Không có tiếp tuyến. <br/> The tangent line does not exist."}], "answers": ["uuid4"]}, {"id": "2733", "text": "Cho $C$ là đường cong được cho bởi $y=f(x)$. Giả sử $f'(x_0)=1$ và $f''(x_0)=2$. Khi đó, độ cong của đường cong tại điểm $(x_0,f(x_0))$ là\n<br/><br/>\nLet $C$ be the curve given by $y=f(x)$. Suppose that $f'(x_0)=1$ and $f''(x_0)=2$. Then the curvature of the curve at the point $(x_0,f(x_0))$ is", "type": "single", "options": [{"id": "uuid1", "text": "$\\frac{2}{\\sqrt{2}}$."}, {"id": "uuid2", "text": "$\\frac{1}{5\\sqrt{5}}$."}, {"id": "uuid3", "text": "$\\frac{2}{5\\sqrt{5}}$."}, {"id": "uuid4", "text": "$\\frac{1}{\\sqrt{2}}$."}], "answers": ["uuid4"]}, {"id": "2682", "text": "Độ cong tại điểm ứng với $t=0$ của đường cong $\\begin{cases}\nx=e^t+\\sinh t,\\\\\ny=e^t-\\cosh t,\n\\end{cases}$ là\n<br/><br/>\nThe curvature at the point corresponding $t=0$ of the curve given by $\\begin{cases}\nx=e^t+\\sinh t,\\\\\ny=e^t-\\cosh t,\n\\end{cases}$ is", "type": "single", "options": [{"id": "uuid1", "text": "$\\frac{3}{5\\sqrt{5}}$."}, {"id": "uuid2", "text": "$\\frac{1}{5\\sqrt{5}}$."}, {"id": "uuid3", "text": "$\\frac{4}{5\\sqrt{5}}$."}, {"id": "uuid4", "text": "$\\frac{2}{5\\sqrt{5}}$."}], "answers": ["uuid2"]}, {"id": "2930", "text": "Cho đường cong tham số: $\\begin{cases}\nx = \\dfrac{1}{2}t^2 + t, \\\\\n\\\\\ny = \\dfrac{1}{3}t^3 + t^2 + t,\n\\end{cases}$.\nTìm phương trình tiếp tuyến của đường cong tại điểm $ A(0; 0)$.  <br/><br/> Given the parametric curve: $\\begin{cases}\nx = \\dfrac{1}{2}t^2 + t, \\\\\n\\\\\ny = \\dfrac{1}{3}t^3 + t^2 + t,\n\\end{cases}$ find an equation of the  tangent line  to the curve at $A(0, 0)$.", "type": "single", "options": [{"id": "uuid1", "text": "$y = x$"}, {"id": "uuid2", "text": "$y = -x$"}, {"id": "uuid3", "text": "$y = 2x - 2$"}, {"id": "uuid4", "text": "$y = -2x + 4$"}], "answers": ["uuid1"]}, {"id": "2926", "text": "Cho đường cong $y = x^2 - 2x + 3$. Tìm phương trình tiếp tuyến của đường cong tại điểm $M(2;3)$.  <br/> Given the curve $y = x^2 - 2x + 3$, find an equation of the tangent line to the curve at the point $M(2, 3)$.", "type": "single", "options": [{"id": "uuid1", "text": "$y = 2x - 1$"}, {"id": "uuid2", "text": "$y = 4x - 5$"}, {"id": "uuid3", "text": "$y = 5$"}, {"id": "uuid4", "text": "$y = x + 2$"}], "answers": ["uuid1"]}, {"id": "2581", "text": "Cho đường cong $C$ có phương trình $f(x,y)=0$. Điểm $M(a,b)\\in C$ được gọi là điểm chính quy nếu:\n<br/><br/>\nGiven a curve $C$ with equation $f(x,y)=0$, a point $M(a,b)\\in C$ is called a regular point if", "type": "multi", "options": [{"id": "uuid1", "text": "$[f_x'(a,b)]^2+[f_y'(a,b)]^2=0$."}, {"id": "uuid2", "text": "$[f_x'(a,b)]^2+[f_y'(a,b)]^2>0$."}, {"id": "uuid3", "text": "$[f_x'(a,b)]^4+[f_y'(a,b)]^4>0$."}, {"id": "uuid4", "text": "$[f_x'(a,b)]^4+[f_y'(a,b)]^4=0$."}], "answers": ["uuid2", "uuid3"]}, {"id": "2671", "text": "Trong các điểm sau, những điểm nào là điểm nào chính quy của đường cong $C$ được cho bởi phương trình $y^2(y-1)^2-x^2=0$? <br/><br/> Which of the followings are regular points of the curve $C$ given by the equation $y^2(y-1)^2-x^2=0$?", "type": "multi", "options": [{"id": "uuid1", "text": "$(0;0)$."}, {"id": "uuid2", "text": "$(2;2)$."}, {"id": "uuid3", "text": "$(6;3)$."}, {"id": "uuid4", "text": "$(0;1)$."}], "answers": ["uuid2", "uuid3"]}]}, {"number": 5, "title": "Trường vô hướng", "questions": [{"id": "2679", "text": "Gradient của $u=xy+3z+\\ln(1+x^2+y^2)$ tại điểm $M(1;0;-1)$ là: <br/><br/>\n     \nGradient of $u=xy+3z+\\ln(1+x^2+y^2)$ at $M(1,0,-1)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$(1;-1;3)$. <br/>$\\langle1,-1,3\\rangle.$"}, {"id": "uuid2", "text": "$(1;-1;-3)$. <br/>$ \\langle1,-1,-3\\rangle.$"}, {"id": "uuid3", "text": "$(1;1;3)$. <br/> $\\langle1,1,3\\rangle.$"}, {"id": "uuid4", "text": "$(1;1;-3)$. <br/>$\\langle1,1,-3\\rangle.$"}], "answers": ["uuid3"]}, {"id": "2718", "text": "Cho $u, v\\colon {\\mathbb R}^3\\to {\\mathbb R}$ ,  $f\\colon {\\mathbb R}\\to {\\mathbb R}$ là các trường vô hướng. Chọn các tính chất đúng của gradient:<br/> <br/>Let $u, v\\colon  {\\mathbb R}^3\\to {\\mathbb R}$ ,  $f\\colon {\\mathbb R}\\to {\\mathbb R}$ be scalar fields. Select the correct properties of the gradient:", "type": "multi", "options": [{"id": "uuid1", "text": "${\\overrightarrow{\\rm grad}} \\ (u.v)=u . {\\overrightarrow{\\rm grad}} \\ v+v.{\\overrightarrow{\\rm grad}} \\ u$. <br/>\n$\\nabla (u.v)=u . \\nabla v+v. \\nabla u$."}, {"id": "uuid2", "text": "${\\overrightarrow{\\rm grad}} \\ (u.v)={\\overrightarrow{\\rm grad}} \\ u . {\\overrightarrow{\\rm grad}} \\ v$. <br/>\n$\\nabla (u.v)=\\nabla u \\cdot \\nabla v$."}, {"id": "uuid3", "text": "${\\overrightarrow{\\rm grad}} \\ f(u)=f'(u) . {\\overrightarrow{\\rm grad}} \\ u$. <br/>\n$\\nabla f(u)=f'(u) . \\nabla u$."}, {"id": "uuid4", "text": "${\\overrightarrow{\\rm grad}} \\ f(u)={\\overrightarrow{\\rm grad}} \\ f . {\\overrightarrow{\\rm grad}} \\ u$. <br/>\n$\\nabla f(u)=\\nabla f . \\nabla u$."}], "answers": ["uuid1", "uuid3"]}, {"id": "2683", "text": "Đặt $\\alpha$ là góc giữa các gradient của $u=\\dfrac{x+y+z}{x^2+y^2+z^2}$ tai các điểm $A(1;1;1)$ và $B(-1;1;0)$.  Khi đó:\n\n   <br/>   <br/>\n   \n       Let $\\alpha$ be the angle between the gradients of $u=\\dfrac{x+y+z}{x^2+y^2+z^2}$ at $A(1,1,1)$ and $B(-1,1,0)$. Then", "type": "single", "options": [{"id": "uuid1", "text": "$\\cos \\alpha =1$."}, {"id": "uuid2", "text": "$\\cos \\alpha =-1$."}, {"id": "uuid3", "text": "$\\cos \\alpha =1/3$."}, {"id": "uuid4", "text": "$\\cos \\alpha =-1/3$."}], "answers": ["uuid2"]}, {"id": "2713", "text": "Cho trường vô hướng $u=x^2y^3+2z$ và điểm $  A(1;1;1)$.  Khi đó,  $|{\\overrightarrow{\\rm grad}} \\ u(A)|$ bằng<br/> <br/>Let $u=x^2y^3+2z$ be a scalar field and let $  A(1,1,1)$ be a point.  Then,  $|{\\overrightarrow{\\rm grad}} \\ u(A)|$ ($|\\nabla u(A)|$) is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$\\sqrt{17}$."}, {"id": "uuid2", "text": "$(1;1;1)$."}, {"id": "uuid3", "text": "$22$."}, {"id": "uuid4", "text": "$(2;3;2)$."}], "answers": ["uuid1"]}, {"id": "2717", "text": "Cho  trường vô hướng $u=x^3+x^2+x^2y+z^3+xyz$ và hai điểm $A(0;1;1), \\ B(1; 2; 3)$.  Các khẳng định nào sau đây là đúng?<br/> <br/>Let $u=x^3+x^2+x^2y+z^3+xyz$ be a scalar field, and  let $A(0, 1, 1), \\ B(1, 2, 3)$ be two points.  Which of the following conclusions are correct?", "type": "multi", "options": [{"id": "uuid2", "text": "$\\frac{\\partial u}{\\partial \\overrightarrow{AB}}(A)=\\frac{7}{\\sqrt{6}}$."}, {"id": "uuid3", "text": "$\\frac{\\partial u}{\\partial \\overrightarrow{AB}}(A)=\\frac{8}{\\sqrt{6}}$."}, {"id": "uuid4", "text": "${\\overrightarrow{\\rm grad}} \\ u(A)=(1; -1; 3)$.<br/> $\\nabla u(A)=\\langle 1, -1, 3\\rangle$."}, {"id": "uuid5", "text": "${\\overrightarrow{\\rm grad}} \\ u(A)=(1; 0; 3)$.<br/> \n\n$\\nabla u(A)=\\langle 1, 0, 3\\rangle$."}], "answers": ["uuid2", "uuid5"]}, {"id": "2680", "text": "Đạo hàm của $u=e^x(y^2+z)-2xyz^3$ theo hướng $\\overrightarrow{\\ell}=(1;2;-2)$ tại $A(0;1;2)$ là:    <br/><br/>\n      \nThe directional derivative of $u=e^x(y^2+z)-2xyz^3$ in the direction of $\\overrightarrow{\\ell}=\\langle 1,2,-2\\rangle$ at  $A(0,1,2)$  is", "type": "single", "options": [{"id": "uuid1", "text": "$\\dfrac{3}{11}$."}, {"id": "uuid2", "text": "$-\\dfrac{3}{11}$."}, {"id": "uuid3", "text": "$\\dfrac{11}{3}$."}, {"id": "uuid4", "text": "$-\\dfrac{11}{3}$."}], "answers": ["uuid4"]}, {"id": "2689", "text": "Tốc độ biến thiên cực đại của hàm số $u=x^2+xy^2-yz$ tại điểm $M(1;-1;1)$ là:   <br/><br/>\n    \nThe maximum rate of change of $u=x^2+xy^2-yz$ at the point $M(1,-1,1)$ is:", "type": "single", "options": [{"id": "uuid1", "text": "$\\sqrt{19}$."}, {"id": "uuid2", "text": "$\\sqrt{15}$."}, {"id": "uuid3", "text": "$19$."}, {"id": "uuid4", "text": "$15$."}], "answers": ["uuid1"]}, {"id": "2677", "text": "Trong $\\mathbb{R^3}$ cho hai điểm $M(0;1;-1)$ và $M_0(2;-1;-2)$. Đạo hàm của $u=xy+z^3$ theo hướng $\\overrightarrow{M_0M}$ tại $M$ là: <br><br>\n\n  Let $M(0,1,-1)$ and $M_0(2,-1,-2)$ be two points in $\\mathbb{R^3}$. The directional derivative of $u=xy+z^3$ at     $M$  in the direction of the vector $\\overrightarrow{M_0M}$ is", "type": "single", "options": [{"id": "uuid1", "text": "$1$."}, {"id": "uuid2", "text": "$-1$."}, {"id": "uuid3", "text": "$\\dfrac{1}{3}$."}, {"id": "uuid4", "text": "$-\\dfrac{1}{3}$."}], "answers": ["uuid3"]}, {"id": "2715", "text": "Cho trường vô hướng  $u=x^2y^3$, điểm $ A(1; 2)$ và véc tơ $\\vec{\\ell}=(2;3)$.  Khi đó, $\\frac{\\partial u}{\\partial \\vec{\\ell}}(A)$ bằng<br/> <br/>Let  $u=x^2y^3$ be a scalar field, $ A(1, 2)$ be a point,  and $\\vec{\\ell}=\\langle 2,3\\rangle$ be a vector.  Then, $\\frac{\\partial u}{\\partial \\vec{\\ell}}(A)$ is equal to", "type": "single", "options": [{"id": "uuid1", "text": "$\\dfrac{68}{\\sqrt{13}}$."}, {"id": "uuid2", "text": "$\\dfrac{36}{\\sqrt{13}}$."}, {"id": "uuid3", "text": "$68$."}, {"id": "uuid4", "text": "$36$."}], "answers": ["uuid1"]}, {"id": "2687", "text": "Tìm tất cả các giá trị của $a$ sao cho gradient của hàm số $u=x^2-2xy+2z$ tại điểm $M(1;0;-1)$ vuông góc với véc tơ $\\overrightarrow{\\ell}=(a^2;2;-2)$.  <br/><br/>\n     \nFind all values of $a$ such that the gradient of the function $u=x^2-2xy+2z$ at the point $M(1,0,-1)$ is orthogonal to the vector $\\overrightarrow{\\ell}=(a^2,2,-2)$.", "type": "multi", "options": [{"id": "uuid1", "text": "$a=1$"}, {"id": "uuid2", "text": "$a=2$"}, {"id": "uuid3", "text": "$a=-1$"}, {"id": "uuid4", "text": "$a=-2$"}], "answers": ["uuid2", "uuid4"]}, {"id": "2714", "text": "Cho trường vô hướng $u=x+y^2+z^3$. Các kết luận nào sau đây đúng?<br/> <br/>Let  $u=x+y^2+z^3$ be a scalar field. Which of the following conclusions are correct?", "type": "multi", "options": [{"id": "uuid1", "text": "${\\overrightarrow{\\rm grad}} \\ u = \\vec{i}+2y\\vec{j}+3z^2\\vec{k}.$<br/> $\\nabla u = \\vec{i}+2y\\vec{j}+3z^2\\vec{k}.$"}, {"id": "uuid2", "text": "${\\overrightarrow{\\rm grad}} \\ u (1;1;0)=\\vec{i}+2\\vec{j}$.<br/> \n$\\nabla  u (1,1,0)=\\vec{i}+2\\vec{j}$."}, {"id": "uuid3", "text": "${\\overrightarrow{\\rm grad}} \\ u =x+2y+3z^2$.<br/> $\\nabla  u =x+2y+3z^2$."}, {"id": "uuid4", "text": "${\\overrightarrow{\\rm grad}} \\ u (1;0;1) =4$.<br/> $\\nabla  u (1,0,1) =4$."}], "answers": ["uuid1", "uuid2"]}, {"id": "2720", "text": "Cho trường vô hướng $u=\\dfrac{x}{x^2+y^2+z^2}$ và hai điểm $A(1; 2; 2), B(-3; 1; 0)$. Các khẳng định nào sau đây là đúng?<br/> <br/>Let  $u=\\dfrac{x}{x^2+y^2+y^2}$ be a scalar field and let $A(1, 2, 2), B(-3, 1, 0)$ be two points. Which of the following conclusions are correct?", "type": "multi", "options": [{"id": "uuid1", "text": "${\\overrightarrow{\\rm grad}} \\ u(A)=\\dfrac{1}{81}(7, -4, -4) $. $\\quad$ $\\left[\\nabla u(A)=\\dfrac{1}{81}\\langle 7, -4, -4\\rangle. \\right]$"}, {"id": "uuid2", "text": "${\\overrightarrow{\\rm grad}} \\ u(B)=\\big(-\\dfrac{2}{25}, \\dfrac{3}{50}, 0\\big)$.  $\\quad $ $\\left[\\nabla u(B)=\\langle -\\dfrac{2}{25}, \\dfrac{3}{50}, 0\\rangle.\\right]$."}, {"id": "uuid3", "text": "Góc giữa ${\\overrightarrow{\\rm grad}} \\ u(A)$ và ${\\overrightarrow{\\rm grad}} \\ u(B)$ là $\\alpha$, với $\\cos \\alpha=\\dfrac{-8}{9}$.<br/> The angle between two vectors $\\nabla u(A)$ and $\\nabla  u(B)$ is  $\\alpha$, with $\\cos \\alpha=\\dfrac{-8}{9}$."}, {"id": "uuid4", "text": "Góc giữa ${\\overrightarrow{\\rm grad}} \\ u(A)$ và ${\\overrightarrow{\\rm grad}} \\ u(B)$ là $\\alpha$, với $\\cos \\alpha=\\frac{-2}{3}$.<br/> The angle between two vectors  $\\nabla  u(A)$ and $\\nabla   u(B)$ is $\\alpha$, with $\\cos \\alpha=\\dfrac{-2}{3}$."}, {"id": "uuid5", "text": "${\\overrightarrow{\\rm grad}} \\ u(A)=\\dfrac{1}{8}(3, 4, 2) $. $\\quad $ $\\left[\\nabla  u(A)=\\dfrac{1}{8}\\langle 3, 4, 2\\rangle. \\right]$"}, {"id": "uuid6", "text": "${\\overrightarrow{\\rm grad}} \\ u(B)=\\big(\\dfrac{2}{21}, \\dfrac{3}{50}, 0\\big) $. $\\quad $ $\\left[\\nabla u(B)=\\langle \\dfrac{2}{21}, \\dfrac{3}{50}, 0\\rangle.\\right] $"}], "answers": ["uuid1", "uuid2", "uuid3"]}, {"id": "2681", "text": "Gọi $\\overrightarrow{n}$ là véc tơ pháp tuyến hướng ra ngoài của mặt cầu $x^2+y^2+z^2=3$ tại điểm $A(1;1;-1)$. Đạo hàm của $u=x^3-3x^2y+2yz^2$ theo hướng $\\overrightarrow{n}$ tại điểm $A$ là:  <br/><br/>\n          \n      Let $\\overrightarrow{n}$ be an outward normal vector to the sphere $x^2+y^2+z^2=3$ at $A(1,1,-1)$. The directional derivative of $u=x^3-3x^2y+2yz^2$ in the direction of $\\overrightarrow{n}$ at $A$ is", "type": "single", "options": [{"id": "uuid1", "text": "$6\\sqrt{3}$."}, {"id": "uuid2", "text": "$-6\\sqrt{3}$."}, {"id": "uuid3", "text": "$3\\sqrt{3}$."}, {"id": "uuid4", "text": "$0$."}], "answers": ["uuid4"]}, {"id": "2719", "text": "Cho trường vô hướng $u=2xy^2-6z$ và điểm $  A(2; 1; 2)$. Các khẳng định nào sau đây là đúng? <br/><br/>\nLet $u=2xy^2-6z$ be a scalar field and let $  A(2, 1, 2)$ be a point. Which of the following conclusions are correct?", "type": "multi", "options": [{"id": "uuid1", "text": "$\\dfrac{\\partial u}{\\partial \\vec{l}}(A)$  đạt giá trị bé nhất khi $\\vec{\\ell}=(-1; -4; 3)$.<br/>$\\dfrac{\\partial u}{\\partial \\vec{\\ell}}(A)$  reaches its minimum value when $\\vec{l}=\\langle -1, -4, 3\\rangle$."}, {"id": "uuid2", "text": "$\\dfrac{\\partial u}{\\partial \\vec{l}}(A)$  đạt giá trị lớn nhất khi $\\vec{\\ell}=(1; 4; -3)$.<br/> $\\dfrac{\\partial u}{\\partial \\vec{l}}(A)$  reaches its maximum value when $\\vec{\\ell}=\\langle 1, 4, -3\\rangle$."}, {"id": "uuid3", "text": "${\\overrightarrow{\\rm grad}} \\ u(A)=(2; 8; -6)$.<br/>$\\nabla u(A)=\\langle 2, 8, -6\\rangle$."}, {"id": "uuid4", "text": "${\\overrightarrow{\\rm grad}} \\ u(A)=(-2; -8; 6)$.<br/> $\\nabla u(A)=\\langle -2, -8, 6\\rangle$."}, {"id": "uuid5", "text": "$\\dfrac{\\partial u}{\\partial \\vec{\\ell}}(A)$  đạt giá trị bé nhất khi $\\vec{\\ell}=(1; 4; -3)$. <br/>$\\dfrac{\\partial u}{\\partial \\vec{\\ell}}(A)$  reaches its minimum value when $\\vec{\\ell}=\\langle 1, 4, -3\\rangle$."}, {"id": "uuid6", "text": "$\\dfrac{\\partial u}{\\partial \\vec{l}}(A)$  đạt giá trị lớn nhất khi $\\vec{\\ell}=(-1; -4; 3)$.<br/> $\\dfrac{\\partial u}{\\partial \\vec{l}}(A)$  reaches its maximum value when $\\vec{\\ell}=\\langle-1, -4, 3\\rangle$."}], "answers": ["uuid1", "uuid2", "uuid3"]}, {"id": "2721", "text": "Cho trường vô hướng $u=x^3+3y^2z^2+7xyz$ và $\\vec{n}$  là véc tơ pháp tuyến hướng vào trong của mặt cầu  $S: x^2+y^2+z^2=3$ tại điểm  $M(-1; 1; 1)$. Các khẳng định nào sau đây là đúng?<br/> <br/> Let $u=x^3+3y^2z^2+7xyz$ be a scalar field and let $\\vec{n}$  be the inward unit normal vector of the surface  $S: x^2+y^2+z^2=3$ at the point  $M(-1, 1, 1)$. Which of the following conclusions are correct?", "type": "multi", "options": [{"id": "uuid1", "text": "${\\overrightarrow{\\rm grad}} \\ u(M)=(10; -1; -1)$ . $\\quad$ $\\left[\\nabla u(M)=\\langle 10, -1, -1\\rangle.\\right]$"}, {"id": "uuid3", "text": "${\\overrightarrow{\\rm grad}} \\ u(M)=(10;1; -1)$ .$\\quad$ $ \\left[\\nabla u(M)=\\langle10, 1, -1\\rangle.\\right]$ ."}, {"id": "uuid4", "text": "$\\vec{n} =(-\\dfrac{1}{\\sqrt{3}}, \\dfrac{1}{\\sqrt{3}}, \\dfrac{1}{\\sqrt{3}})$."}, {"id": "uuid5", "text": "$\\dfrac{\\partial u}{\\partial \\vec{n}}(M)=4\\sqrt{3}$."}], "answers": ["uuid1", "uuid5"]}, {"id": "2685", "text": "Giả sử $\\overrightarrow{\\ell}=(0;a;a^2-b^2)$ là hướng mà hàm số $u=x\\sin z-y\\cos z$ biến thiên cực đại tại điểm $O(0;0;0)$. Khi đó những khẳng định nào sau đây là đúng?\n   <br/><br/>\nSuppose that $\\overrightarrow{\\ell}=(0,a,a^2-b^2)$ is the direction in which the function $u=x\\sin z-y\\cos z$ has the maximum rate of change at $O(0,0,0)$. Which of the following statements are correct?", "type": "multi", "options": [{"id": "uuid1", "text": "$a=1; b=1$."}, {"id": "uuid2", "text": "$a=-1; b\\in \\{-1,1\\}$."}, {"id": "uuid3", "text": "$a=1;b=-1$"}, {"id": "uuid4", "text": "$a+|b|=0$."}], "answers": ["uuid2", "uuid4"]}, {"id": "2716", "text": "Cho trường vô hướng  $u=r^2+\\ln r$ với $r=\\sqrt{x^2+y^2+z^2}$.  Các khẳng định nào sau đây là đúng?<br/> <br/>Let   $u=r^2+\\ln r$ with $r=\\sqrt{x^2+y^2+z^2}$ be a scalar field.  Which of the following statements are correct?", "type": "multi", "options": [{"id": "uuid1", "text": "${\\overrightarrow{\\rm grad}} \\ u=\\dfrac{2(x^2+y^2+z^2)+1}{x^2+y^2+z^2}(x, y, z)$. <br/> $\\nabla u=\\dfrac{2(x^2+y^2+z^2)+1}{x^2+y^2+z^2}\\langle x, y, z\\rangle$."}, {"id": "uuid2", "text": "$|{\\overrightarrow{\\rm grad}} \\ u(1;0; 0)|=3$. <br/>\n$|\\nabla u(1, 0, 0)|=3$."}, {"id": "uuid3", "text": "${\\overrightarrow{\\rm grad}} \\ u=\\dfrac{(x^2+y^2+z^2)+1}{x^2+y^2+z^2}(x, y, z)$. <br/>\n$\\nabla u=\\dfrac{(x^2+y^2+z^2)+1}{x^2+y^2+z^2}\\langle x, y, z\\rangle$."}, {"id": "uuid4", "text": "$|{\\overrightarrow{\\rm grad}} \\ u(0;1; 0)|=2$.<br/>\n$|\\nabla u(0, 1, 0)|=2$."}], "answers": ["uuid1", "uuid2"]}, {"id": "2722", "text": "Cho trường vô hướng $u=x^3+2y^3+3z^2+2xyz$. Các khẳng định nào sau đây là đúng?<br/> <br/>Let  $u=x^3+2y^3+3z^2+2xyz$ be a scalar field. Which of the following conclusions are correct?", "type": "multi", "options": [{"id": "uuid1", "text": "${\\overrightarrow{\\rm grad}} \\ u$ vuông góc với trục  $Ox$ khi $3x^2+2yz=0$.<br/> $\\nabla u$  is perpendicular to the $x$-axis when  $3x^2+2yz=0$."}, {"id": "uuid2", "text": "${\\overrightarrow{\\rm grad}} \\ u$ vuông góc với  trục $Oz$ khi $3z+xy=0$.<br/> $\\nabla  u$  is perpendicular to the $z$-axis when  $3z+xy=0$."}, {"id": "uuid3", "text": "${\\overrightarrow{\\rm grad}} \\ u$ vuông góc với  trục $Oy$ khi $4y^2+xz=0$.<br/> $\\nabla u$ is perpendicular to the $y$-axis when  $4y^2+xz=0$."}, {"id": "uuid4", "text": "${\\overrightarrow{\\rm grad}} \\ u$ vuông góc với  trục $Oz$ khi $6z+xy=0$.<br/>$\\nabla u$ is perpendicular to the $z$-axis when  $6z+xy=0$."}], "answers": ["uuid1", "uuid2"]}, {"id": "2684", "text": "Tốc độ biến thiên cực đại của trường vô hướng $u=x^2-xy+2yz$ tại điểm $M(1;-1;0)$ là:\n   \n   <br/>   <br/>\n    \n       The maximum rate of change of $u=x^2-xy+2yz$ at the point $M(1,-1,0)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$\\sqrt{14}$"}, {"id": "uuid2", "text": "$\\sqrt{15}$"}, {"id": "uuid3", "text": "$4$"}, {"id": "uuid4", "text": "$5$"}], "answers": ["uuid1"]}, {"id": "2688", "text": "Theo hướng nào sau đây thì tốc độ biến thiên của hàm số $u=x^2+2xy-z$ tại điểm $M(0;-1;1)$ là lớn nhất?\n  <br/><br/>\n    In which of the following directions is the rate of change of $u=x^2+2xy-z$ at the point $M(0,-1,1)$  maximal?", "type": "single", "options": [{"id": "uuid1", "text": "$\\overrightarrow{\\ell}=(2;1;0)$."}, {"id": "uuid2", "text": "$\\overrightarrow{\\ell}=(-2;1;0)$."}, {"id": "uuid3", "text": "$\\overrightarrow{\\ell}=(-2;0;1)$."}, {"id": "uuid4", "text": "$\\overrightarrow{\\ell}=(-2;0;-1)$."}], "answers": ["uuid4"]}]}, {"number": 6, "title": "Ứng dụng của phép tính vi phân trong hình học không gian", "questions": [{"id": "2610", "text": "Cho $S$ là mặt cong được cho bởi phương trình $f(x,y,z)=0$. Điểm $P(a,b,c)$ được gọi là điểm chính quy nếu\n<br/><br/>\nLet $S$ be the surface given by $f(x,y,z)=0$. A point $P(a,b,c)$ is called a regular point if", "type": "multi", "options": [{"id": "uuid1", "text": "$|f_x'(a,b,c)|+|f_y'(a,b,c)|+|f_z'(a,b,c)|=0$."}, {"id": "uuid2", "text": "$|f_x'(a,b,c)|+|f_y'(a,b,c)|+|f_z'(a,b,c)|>0$."}, {"id": "uuid3", "text": "$|f_x'(a,b,c)|^2+|f_y'(a,b,c)|^2+|f_z'(a,b,c)|^2>0$."}, {"id": "uuid4", "text": "$|f_x'(a,b,c)|^2+|f_y'(a,b,c)|^2+|f_z'(a,b,c)|^2=0$."}], "answers": ["uuid2", "uuid3"]}, {"id": "2608", "text": "Cho $S$ là mặt cong được cho bởi phương trình $x^2+y^2+z^2-256=0$. Phương trình tiếp diện của mặt $S$ tại điểm $P(0;0;16)$ là\n<br/><br/>\nLet $S$ be the surface given by $x^2+y^2+z^2-256=0$. Then the tangent plane of the surface $S$ at the point $P(0;0;16)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$x=z=0$."}, {"id": "uuid2", "text": "$y=16$."}, {"id": "uuid3", "text": "$z=16$."}, {"id": "uuid4", "text": "$x=16$."}], "answers": ["uuid3"]}, {"id": "2609", "text": "Hoàn thiện phát biểu định nghĩa về giới hạn $\\lim\\limits_{t\\to t_0}\\overrightarrow{r}(t)=\\overrightarrow{a}$.\n<br/><br/>\nComplete the definition of the limit $\\lim\\limits_{t\\to t_0}\\overrightarrow{r}(t)=\\overrightarrow{a}$.", "type": "single", "options": [{"id": "uuid1", "text": "$\\forall\\varepsilon>0,\\exists\\delta$: $|\\overrightarrow{r}(t)-\\overrightarrow{a}|<\\varepsilon$ khi (provided that) $0<|t-t_0|<\\delta$."}, {"id": "uuid2", "text": "$\\forall\\varepsilon>0,\\exists\\delta>0$: $|\\overrightarrow{r}(t)-\\overrightarrow{a}|<\\varepsilon$ khi (provided that) $t-t_0<\\delta$."}, {"id": "uuid3", "text": "$\\forall\\varepsilon>0,\\exists\\delta>0$: $|\\overrightarrow{r}(t)-\\overrightarrow{a}|<\\varepsilon$ khi (provided that) $0<|t-t_0|<\\delta$."}, {"id": "uuid4", "text": "$\\forall\\varepsilon>0,\\exists\\delta>0$: $|\\overrightarrow{r}(t)-\\overrightarrow{a}|<\\varepsilon$ khi (provided that) $|t-t_0|<\\delta$."}], "answers": ["uuid3"]}, {"id": "2759", "text": "Cho $S$ là mặt cong được xác định bởi phương trình $x^3y^4z^5=1$. Trong các điểm sau đây, những  điểm nào là điểm chính quy của $S$?\n<br/><br/>\nLet $S$ be the surface given by $x^3y^4z^5=1$. Which of the following points are regular points of $S$?", "type": "multi", "options": [{"id": "uuid1", "text": "$(0;1;1)$."}, {"id": "uuid2", "text": "$(-1;1;-1)$."}, {"id": "uuid3", "text": "$(1;-1;1)$."}, {"id": "uuid4", "text": "$(1;1;-1)$."}], "answers": ["uuid2", "uuid3"]}, {"id": "2790", "text": "Cho đường cong  $C$ là giao của mặt trụ $9x^2 + y^2 =9$ và mặt phẳng $2x - z =3$. Tính độ cong của đường cong $C$ tại điểm $M(1; 0; -1)$.<br/><br/>Given a curve $C$ that is the intersection of the cylinder $9x^2 + y^2 =9$ and the plane $2x - z =3$, calculate the curvature of the curve $C$ at point $M(1, 0, -1)$.", "type": "single", "options": [{"id": "uuid1", "text": "$0$."}, {"id": "uuid2", "text": "$\\frac{\\sqrt{5}}{9}$."}, {"id": "uuid3", "text": "$1$."}, {"id": "uuid4", "text": "$\\frac{1}{3}$."}], "answers": ["uuid2"]}, {"id": "2792", "text": "Phương trình tiếp tuyến của đường cong \n$\n\\begin{cases}\nx^2 + y^2 =20 \\\\\ny^2 + z^2 =45\n\\end{cases}\n$\ntại điểm $A(2;4;\\sqrt{29})$ là:<br/><br/>The tangent line of the curve \n\n$\\begin{cases}\nx^2 + y^2 =20 \\\\\ny^2 + z^2 =45\n\\end{cases}$\n\nat the point $A(2,4,\\sqrt{29})$ is", "type": "single", "options": [{"id": "uuid1", "text": "$x=10-2t, y=t, z=45/\\sqrt{29} - (4/\\sqrt{29})t$."}, {"id": "uuid2", "text": "$x=10+2t, y=t, z=45/\\sqrt{29} + (4/\\sqrt{29})t$."}, {"id": "uuid3", "text": "$x=10-2t, y=t, z=45/\\sqrt{29} + (4/\\sqrt{29})t$."}, {"id": "uuid4", "text": "$x=10+2t, y=t, z=45/\\sqrt{29} - (4/\\sqrt{29})t$."}], "answers": ["uuid1"]}, {"id": "2758", "text": "Cho $S$ là mặt cong được xác định bởi phương trình $xy^2z^3=1$. Tìm vectơ pháp tuyến của $S$ tại điểm $(1;1;1)$.\n<br/><br/>\nLet $S$ be the surface given by $xy^2z^3=1$. Find a normal vector to the surface $S$ at the point $(1,1,1)$.", "type": "single", "options": [{"id": "uuid1", "text": "$(1;1;1)$."}, {"id": "uuid2", "text": "$(3;2;1)$."}, {"id": "uuid3", "text": "$(1;2;3)$."}, {"id": "uuid4", "text": "$(2;1;3)$."}], "answers": ["uuid3"]}, {"id": "2783", "text": "Giả sử $\\vec{u}(t)$ và $\\vec{v}(t)$ là các hàm véctơ khả vi. Khi đó, đạo hàm của tổng hai hàm véctơ này là:<br/>Suppose that $\\vec{u}(t)$ and $\\vec{v}(t)$ are differentiable vector functions. Then the derivative of the sum of these two vector functions is:", "type": "single", "options": [{"id": "uuid1", "text": "$\\vec{u}(t) - \\vec{v}(t)$."}, {"id": "uuid2", "text": "$\\frac{d\\vec{u}(t)}{dt} + \\frac{d\\vec{v}(t)}{dt}$."}, {"id": "uuid3", "text": "$\\frac{d\\vec{u}(t)}{dt} \\times \\frac{d\\vec{v}(t)}{dt}$."}, {"id": "uuid4", "text": "$\\frac{d\\vec{u}(t)}{dt} \\cdot \\frac{d\\vec{v}(t)}{dt}$."}], "answers": ["uuid2"]}, {"id": "2784", "text": "Đạo hàm của tích vô hướng  $\\vec{a}(t) \\cdot \\vec{b}(t)$ của hai hàm véctơ khả vi $\\vec{a}(t)$ và $\\vec{b}(t)$ là gì?<br/><br/>What is the derivative of the dot product of two differentiable vector functions $\\vec{a}(t)$ and $\\vec{b}(t)$?", "type": "single", "options": [{"id": "uuid1", "text": "$\\vec{a}(t) \\times \\vec{b}(t)$."}, {"id": "uuid2", "text": "$\\vec{a}(t) \\cdot \\vec{b}(t)$."}, {"id": "uuid3", "text": "$\\frac{d\\vec{a}(t)}{dt} \\cdot \\vec{b}(t) + \\vec{a}(t) \\cdot \\frac{d\\vec{b}(t)}{dt}$."}, {"id": "uuid4", "text": "$\\frac{d\\vec{a}(t)}{dt} \\times \\frac{d\\vec{b}(t)}{dt}$."}], "answers": ["uuid3"]}, {"id": "2789", "text": "Cho mặt cong $2x^2 + 3y^2 - z^2 = 12$. Phương trình tiếp diện tại điểm $(1;2;\\sqrt{2})$ là:<br/><br/>\nFor the quadric surface $2x^2 + 3y^2 - z^2 = 12$, an equation for the tangent plane at the point $(1,2,\\sqrt{2})$ is", "type": "single", "options": [{"id": "uuid1", "text": "$4x +6y -2\\sqrt{2}z =0$."}, {"id": "uuid2", "text": "$x + y - \\sqrt{2}z =0$."}, {"id": "uuid3", "text": "$4x +6y -2\\sqrt{2}z =-12$."}, {"id": "uuid4", "text": "$2x +6y -\\sqrt{2}z =12$."}], "answers": ["uuid4"]}, {"id": "2760", "text": "Phương trình nào sau đây xác định một mặt nón?\n<br/><br/>\nWhich of the following equations defines  a cone?", "type": "single", "options": [{"id": "uuid1", "text": "$z=x^2+y^2$."}, {"id": "uuid2", "text": "$y^2=x^2+z^2$."}, {"id": "uuid3", "text": "$x^2+y^2=4$."}, {"id": "uuid4", "text": "$x^2+y^2+z^2=1$."}], "answers": ["uuid2"]}, {"id": "2788", "text": "Cho đường cong không gian $\\vec{r}(t) = (\\sin t, \\cos t, t)$. Độ cong của đường cong tại điểm ứng với $t = \\frac{\\pi}{4}$ là:<br/><br/>Given the space curve $\\vec{r}(t) = \\langle \\sin t, \\cos t, t\\rangle$, the curvature of the curve at the point corresponding to $t = \\frac{\\pi}{4}$ is:", "type": "single", "options": [{"id": "uuid1", "text": "$\\frac{1}{\\sqrt{2}}$."}, {"id": "uuid2", "text": "$\\frac{1}{2}$."}, {"id": "uuid3", "text": "$\\sqrt{2}$."}, {"id": "uuid4", "text": "$\\frac{\\sqrt{2}}{2}$."}], "answers": ["uuid2"]}, {"id": "2757", "text": "Giả sử $\\lim\\limits_{t\\to 0}\\overrightarrow{r}(t)=(1;-1;3)$ và $\\lim\\limits_{t\\to 0}\\overrightarrow{u}(t)=(2;1;-3)$. Khi đó, giới hạn $\\lim\\limits_{t\\to 0}(\\overrightarrow{r}(t)+\\overrightarrow{u}(t))$ bằng\n<br/><br/>\nSuppose that $\\lim\\limits_{t\\to 0}\\overrightarrow{r}(t)=(1;-1;3)$ and $\\lim\\limits_{t\\to 0}\\overrightarrow{u}(t)=(2;1;-3)$. Then the limit $\\lim\\limits_{t\\to 0}(\\overrightarrow{r}(t)+\\overrightarrow{u}(t))$ is", "type": "single", "options": [{"id": "uuid1", "text": "$(0;-3;0)$."}, {"id": "uuid2", "text": "$(0;0;3)$."}, {"id": "uuid3", "text": "$(0;3;0)$."}, {"id": "uuid4", "text": "$(3;0;0)$."}], "answers": ["uuid4"]}, {"id": "2607", "text": "Cho $\\overrightarrow{r}(t)=(\\text{arccot}\\,t,\\frac{1}{t^2+1},3^t)$. Khi đó, đạo hàm $\\overrightarrow{r}'(t)$ là\n<br/><br/>\nLet $\\overrightarrow{r}(t)=(\\text{arccot}\\,t,\\frac{1}{t^2+1},3^t)$. Then the derivative $\\overrightarrow{r}'(t)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$(\\frac{1}{1+t^2},-\\frac{2t}{(1+t^2)^2},3^t\\ln 3)$."}, {"id": "uuid2", "text": "$(-\\frac{1}{1+t^2},-\\frac{2t}{(1+t^2)^2},3^t\\ln 3)$."}, {"id": "uuid3", "text": "$(-\\frac{1}{1+t^2},\\frac{2t}{(1+t^2)^2},3^t\\ln 3)$."}, {"id": "uuid4", "text": "$(-\\frac{1}{1+t^2},-\\frac{2t}{(1+t^2)^2},3^t)$."}], "answers": ["uuid2"]}, {"id": "2793", "text": "Phương trình tiếp diện của mặt cong $x^3 + y^3 - z^3 =1$ tại điểm $(1;1;1)$ là:\n<br/><br/>An equation of the tangent plane to the surface $x^3 + y^3 - z^3 =1$ at the point $(1,1,1)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$3x^2 + 3y^2 - 3z^2 =0$."}, {"id": "uuid2", "text": "$x + y - z =1$."}, {"id": "uuid3", "text": "$3x^2 + 3y^2 - 3z^2 =3$."}, {"id": "uuid4", "text": "$x^2 + y^2 - z^2 =1$."}], "answers": ["uuid2"]}, {"id": "2785", "text": "Nếu $\\vec{s}(t) = \\alpha(t) \\vec{m}(t)$, thì đạo hàm của $\\vec{s}(t)$ là gì?<br/><br/>If $\\vec{s}(t) = \\alpha(t) \\vec{m}(t)$, then  the derivative of $\\vec{s}(t)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$\\alpha(t) \\cdot \\vec{m}(t)$."}, {"id": "uuid2", "text": "$\\alpha(t) \\cdot \\frac{d\\vec{m}(t)}{dt} + \\alpha^{\\prime}(t) \\cdot \\vec{m}(t)$."}, {"id": "uuid3", "text": "$\\frac{d\\alpha(t)}{dt} \\cdot \\frac{d\\vec{m}(t)}{dt}$."}, {"id": "uuid4", "text": "$\\alpha^{\\prime}(t) \\cdot \\vec{m}(t)$."}], "answers": ["uuid2"]}, {"id": "2980", "text": "Cho $S$ là mặt cong được cho bởi phương trình $f(x,y,z)=0$. Điểm $(a,b,c)\\in S$ được gọi là điểm chính quy nếu\n<br/><br/>\nLet $S$ be the surface given by $f(x,y,z)=0$. A point $(a,b,c)\\in S$ is called a regular point if", "type": "multi", "options": [{"id": "uuid1", "text": "$|f_x'(a,b,c)|+|f_y'(a,b,c)|+|f_z'(a,b,c)|=0$."}, {"id": "uuid2", "text": "$|f_x'(a,b,c)|+|f_y'(a,b,c)|+|f_z'(a,b,c)|>0$."}, {"id": "uuid3", "text": "$|f_x'(a,b,c)|^2+|f_y'(a,b,c)|^2+|f_z'(a,b,c)|^2>0$."}, {"id": "uuid4", "text": "$|f_x'(a,b,c)|^2+|f_y'(a,b,c)|^2+|f_z'(a,b,c)|^2=0$."}], "answers": ["uuid2", "uuid3"]}, {"id": "2761", "text": "Cho $C$ là đường cong được xác định bởi $\\overrightarrow{r}(t)$. Giả sử $\\overrightarrow{r}'(0)=(1;0;1)$ và $\\overrightarrow{r}''(0)=(0;1;0)$. Khi đó, độ cong của $C$ tại điểm ứng với $t=0$ là\n<br/><br/>\nLet $C$ be the curve given by $\\overrightarrow{r}(t)$. Suppose that $\\overrightarrow{r}'(0)=(1;0;1)$ and $\\overrightarrow{r}''(0)=(0;1;0)$. Then the curvature of $C$ at the point corresponding to $t=0$ is", "type": "single", "options": [{"id": "uuid1", "text": "$\\frac{1}{\\sqrt{2}}$."}, {"id": "uuid2", "text": "$\\frac{1}{2}$."}, {"id": "uuid3", "text": "$1$."}, {"id": "uuid4", "text": "$\\sqrt{2}$."}], "answers": ["uuid2"]}, {"id": "2606", "text": "Cho $\\overrightarrow{r}(t)=(\\frac{\\sin t}{t},\\frac{e^t-1}{t},\\frac{\\ln(1+t)}{t})$. Khi đó, giới hạn $\\lim\\limits_{t\\to 0}\\overrightarrow{r}(t)$ là\n<br/><br/>\nLet $\\overrightarrow{r}(t)=(\\frac{\\sin t}{t},\\frac{e^t-1}{t},\\frac{\\ln(1+t)}{t})$. Then the limit $\\lim\\limits_{t\\to 0}\\overrightarrow{r}(t)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$+\\infty$."}, {"id": "uuid2", "text": "$(-1;1;1)$."}, {"id": "uuid3", "text": "$(1;1;1)$."}, {"id": "uuid4", "text": "$(1;1;-1)$."}], "answers": ["uuid3"]}, {"id": "2791", "text": "Phương trình tiếp diện của mặt  $z = x^2 + y^2$ tại điểm $(1;1;2)$ là:<br/><br/>An equation of the tangent plane to the surface $z = x^2 + y^2$ at the point $(1,1,2)$ is", "type": "single", "options": [{"id": "uuid1", "text": "$z = 2x + 2y$."}, {"id": "uuid2", "text": "$z + 2 = 2x + 2y$."}, {"id": "uuid3", "text": "$x + y - z =0$."}, {"id": "uuid4", "text": "$2x + 2y + z =6$."}], "answers": ["uuid2"]}]}];
